+// stringToSliceHookFunc splits scalar string values for []string fields on whitespace.
+func stringToSliceHookFunc() mapstructure.DecodeHookFunc {
+	return func(from, to reflect.Type, data interface{}) (interface{}, error) {
+		if from.Kind() != reflect.String || to != reflect.TypeOf([]string{}) {
+			return data, nil
+		}
+
+		fields := strings.Fields(reflect.ValueOf(data).String())
+		if fields == nil {
+			return []string{}, nil
+		}
+
+		return fields, nil
+	}
+}
